function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),3600)}
function duration(sec=0){sec=Number(sec)||0;const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60);return h?`${h}小时${m?m+'分钟':''}`:`${m}分钟`}
function date(ts){return ts?new Date(Number(ts)*1000).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}).replaceAll('/','-'):'—'}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function noteCount(x){return (x.reviewCount||0)+(x.noteCount||0)+(x.bookmarkCount||0)}
function syncUrl(changes={}){const params=new URLSearchParams(location.search);Object.entries(changes).forEach(([key,value])=>value==null||value===''||value==='all'?params.delete(key):params.set(key,String(value)));history.replaceState(null,'',`${location.pathname}${params.size?`?${params}`:''}${location.hash}`)}
function syncBanner(type,title,detail){const banner=$('#syncBanner'),retry=$('#syncRetry');banner.hidden=type==='hidden';document.body.classList.toggle('data-loading',type==='loading');banner.classList.toggle('error',type==='error');$('.sync-spinner').hidden=type!=='loading';$('#syncTitle').textContent=title||'';$('#syncDetail').textContent=detail||'';retry.hidden=type!=='error'}
function emptyState(title,detail,action=''){return `<div class="empty-state"><strong>${esc(title)}</strong><span>${esc(detail)}</span>${action?`<button type="button" data-empty-action="${esc(action)}">${esc(action)}</button>`:''}</div>`}
async function readResponseJson(response){const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('连接器返回了无法识别的响应');return response.json()}
function connectorFetch(path,options={}){return fetch(`${apiBase}${path}`,apiBase?{...options,targetAddressSpace:'loopback'}:options)}
async function api(api_name,params={}){const clean=Object.fromEntries(Object.entries(params).filter(([,v])=>v!==undefined));let res;try{res=await connectorFetch('/api/weread',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({api_name,...clean})})}catch{throw new Error(apiBase?'本机连接器未启动':'本地服务连接失败')}const data=await readResponseJson(res);if(res.status===426)throw new Error(data.message||'微信读书 skill 需要升级');if(!res.ok||data.errcode)throw new Error(data.message||data.errmsg||'数据获取失败');return data}

async function loadInitial(){state.demo=false;state.yearSummaries=new Map();state.yearTimelineStatus=new Map();state.timelineEpoch+=1;syncBanner('loading','正在同步微信读书','读取年度、12 个月、书架和完整笔记索引…');toast('正在建立你的本地阅读档案…');try{const [overall,shelf,notebooks,annualStats]=await Promise.all([api('/readdata/detail',{mode:'overall',baseTime:0}),api('/shelf/sync'),loadNotebooks(),loadAnnual(state.year)]);Object.assign(state,{overall,shelf,notebooks,annualStats,stats:annualStats,mode:'annually'});state.yearSummaries.set(state.year,annualStats);state.yearTimelineStatus.set(state.year,'ready');setupYears();render();syncBanner('hidden');toast('核心数据已完成同步，正在整理阅读生涯…');loadYearTimeline(state.timelineEpoch);if(requestedMode!=='annually')await loadPeriod(requestedMode);return true}catch(e){state.demo=true;syncBanner('error','真实数据暂时没有载入',`${e.message}。当前继续显示演示数据，你可以检查 Key 后重试。`);toast(`${e.message}，当前显示演示数据`);return false}}
async function loadAnnual(year){const annual=api('/readdata/detail',{mode:'annually',baseTime:yearTimestamp(year)}),months=Promise.all(Array.from({length:12},(_,month)=>api('/readdata/detail',{mode:'monthly',baseTime:Math.floor(new Date(year,month,2).getTime()/1000)})));const [summary,details]=await Promise.all([annual,months]);const dailyReadTimes={};details.forEach((data,month)=>Object.entries(data.readTimes||{}).forEach(([ts,value])=>{const d=new Date(Number(ts)*1000);if(d.getFullYear()===Number(year)&&d.getMonth()===month)dailyReadTimes[ts]=value}));return {...summary,dailyReadTimes}}
async function loadPeriod(mode,year=state.year){state.mode=mode;state.year=year;toast('正在切换统计周期…');try{if(state.demo){state.annualStats=state.yearSummaries.get(year)||demo.stats;state.stats=state.annualStats;render();syncUrl({mode,year});return}if(mode==='annually'){state.annualStats=await loadAnnual(year);state.stats=state.annualStats;state.yearSummaries.set(year,state.annualStats);state.yearTimelineStatus.set(year,'ready')}else state.stats=await api('/readdata/detail',{mode,baseTime:mode==='overall'?0:undefined});render();syncUrl({mode,year});toast('统计周期已更新')}catch(e){toast(`周期切换失败：${e.message}`)}}
async function loadNotebooks(){let books=[],lastSort,first,totalNoteCount=0,totalBookCount=0;const seen=new Set();while(true){const data=await api('/user/notebooks',{count:100,...(lastSort?{lastSort}:{})});first??=data;books.push(...(data.books||[]));totalNoteCount=data.totalNoteCount??totalNoteCount;totalBookCount=data.totalBookCount??totalBookCount;if(!data.hasMore||!data.books?.length)break;const next=data.books.at(-1).sort;if(next==null||seen.has(next))throw new Error('笔记分页游标异常');seen.add(next);lastSort=next}return {...first,books,totalNoteCount,totalBookCount}}
function yearTimestamp(y){return Math.floor(new Date(Number(y),0,2).getTime()/1000)}
function setupYears(){const registered=state.overall?.registTime?new Date(state.overall.registTime*1000).getFullYear():nowYear-5;$('#yearSelect').innerHTML=Array.from({length:nowYear-Math.max(registered,2000)+1},(_,i)=>nowYear-i).map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}

function render(){renderLifetime();renderSummary();renderHeat();renderCategories();renderAnnual();renderShelf();renderLongest();renderNotes()}
function statNumber(stats,name){return parseStatCount(stats,name)}
function archiveStartYear(){if(state.overall?.registTime)return new Date(state.overall.registTime*1000).getFullYear();const years=Object.keys(state.overall?.readTimes||{}).map(key=>/^\d{4}$/.test(key)?Number(key):new Date(Number(key)*1000).getFullYear()).filter(year=>Number.isInteger(year)&&year>=2000&&year<=nowYear);return years.length?Math.min(...years):nowYear}
function readingYears(){return Math.max(1,nowYear-archiveStartYear()+1)}
function displayNumber(value){return value==null?'—':Number(value).toLocaleString()}
function enumerableReadingItems(){const items=[],seen=new Set(),add=item=>{const normalized=normalizeReadingItem(item),key=normalized.id?`${normalized.albumId?'album':'book'}:${normalized.id}`:`title:${normalized.title}:${normalized.author}`;if(!normalized.title||seen.has(key))return;seen.add(key);items.push(normalized)};(state.shelf?.books||[]).forEach(add);(state.shelf?.albums||[]).forEach(item=>add(item.albumInfo||item));(state.notebooks?.books||[]).forEach(item=>add({...item.book,...item,bookId:item.bookId||item.book?.bookId,title:item.book?.title||item.title,author:item.book?.author||item.author,cover:item.book?.cover||item.cover}));return items}
function renderLifetime(){const overall=state.overall||{},shelf=state.shelf||{},books=shelf.books||[],albums=shelf.albums||[],hasMp=Boolean(shelf.mp&&Object.keys(shelf.mp).length),shelfTotal=books.length+albums.length+(hasMp?1:0),finished=statNumber(overall,'读完'),readCount=statNumber(overall,'读过'),notes=statNumber(overall,'笔记')??state.notebooks?.totalNoteCount??(state.notebooks?.books||[]).reduce((sum,item)=>sum+noteCount(item),0),finishRate=readCount!=null&&finished!=null&&readCount>0?Math.round(finished/readCount*100):null,topCategory=overall.preferCategory?.[0]?.categoryTitle||'等待数据',habit=overall.preferTimeWord?.replace('偏好','')||'等待数据',hours=overall.totalReadTime==null?null:Math.round(Number(overall.totalReadTime)/3600),days=overall.readDays==null?null:Number(overall.readDays),metrics=[['累计阅读时长',displayNumber(hours),'小时','accent'],['累计阅读天数',displayNumber(days),'天',''],['书架条目',displayNumber(shelfTotal),'个',''],['累计读完',displayNumber(finished),'本','']];document.body.classList.toggle('archive-ready',Boolean(state.overall&&state.shelf));$('#lifetimeMetrics').innerHTML=metrics.map(([label,value,unit,tone])=>`<article class="lifetime-metric ${tone}"><strong>${value}</strong><span>${unit}</span><small>${label}</small></article>`).join('');$('#lifetimeStrip').innerHTML=[['注册至今',`${readingYears()} 年`],['累计读过',readCount==null?'—':`${readCount.toLocaleString()} 本`],['笔记划线',`${Number(notes||0).toLocaleString()} 条`],['累计完读率',finishRate==null?'—':`${finishRate}%`],['偏好',topCategory],['习惯',habit]].map(([label,value])=>`<div><span>${label}</span><strong>${esc(value)}</strong></div>`).join('');renderTitleWheel(enumerableReadingItems());renderYearTimeline();renderLifetimeInsights()}
function categoryTone(category=''){const tones=['#2c5234','#8a500d','#6e6040','#557761','#7c4e3b','#8b7420'];let hash=0;for(const char of category)hash=(hash*31+char.charCodeAt(0))|0;return tones[Math.abs(hash)%tones.length]}
function renderTitleWheel(items){const target=$('#titleWheel');if(!target)return;if(!items.length){target.innerHTML=emptyState('还没有可枚举的读物','同步书架或笔记本后，真实书名会在这里组成你的阅读年轮。');return}const mobile=matchMedia('(max-width:560px)').matches,titles=items.slice(0,mobile?120:280),rings=mobile?9:14;let cursor=0;const paths=Array.from({length:rings},(_,i)=>{const r=(mobile?76:54)+i*(mobile?31:23),id=`title-ring-${i}`,circ=2*Math.PI*r,fontSize=mobile?9:7.2,capacity=Math.max(20,Math.floor(circ/(fontSize*1.16))),parts=[],start=cursor,rotating=i>=rings-3;let used=0,attempts=0;while(used<capacity*.92&&attempts<titles.length*3){const book=titles[cursor%titles.length],units=Math.max(4,[...book.title].length+3);if(used+units>capacity*.97&&parts.length)break;const offset=(used/capacity*100).toFixed(2),tone=categoryTone(book.category),label=`查看《${book.title}》详情`,text=`${esc(book.title)} · `,segment=`<text class="wheel-book-title" fill="${tone}"><textPath href="#${id}" startOffset="${offset}%">${text}</textPath></text>`;parts.push(book.bookId?`<a class="wheel-book" href="?book=${encodeURIComponent(book.bookId)}" data-book="${esc(book.bookId)}" aria-label="${esc(label)}">${segment}</a>`:`<g class="wheel-book wheel-book-static" aria-label="${esc(book.title)}">${segment}</g>`);used+=units;cursor+=1;attempts+=1}if(cursor===start)cursor+=1;return `<g class="title-ring-group ${rotating?'is-rotating':''}" style="--ring:${i}"><path id="${id}" class="title-ring-path" d="M 400,400 m -${r},0 a ${r},${r} 0 1,1 ${r*2},0 a ${r},${r} 0 1,1 -${r*2},0"/>${parts.join('')}</g>`}).join('');target.innerHTML=`<svg viewBox="0 0 800 800" role="img" aria-label="由 ${items.length} 个可枚举读物标题组成的书名年轮"><circle cx="400" cy="400" r="42" class="wheel-core"/><text x="400" y="395" text-anchor="middle" class="wheel-count">${items.length}</text><text x="400" y="417" text-anchor="middle" class="wheel-caption">个读物 · ${readingYears()} 年</text>${paths}</svg><div class="sr-only">${titles.map(book=>esc(book.title)).join('、')}</div>`;target.querySelectorAll('[data-book]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();openBook(link.dataset.book)}))}
function yearReadCount(stats){return statNumber(stats,'读过')}
function yearCovers(stats){const seen=new Set();return (stats?.readLongest||[]).map(entry=>normalizeReadingItem(entry)).filter(item=>{const key=item.id||`${item.title}:${item.author}`;if(!item.title||seen.has(key))return false;seen.add(key);return true}).slice(0,5)}
function yearBucketSeconds(year){const pair=Object.entries(state.overall?.readTimes||{}).find(([key])=>/^\d{4}$/.test(key)?Number(key)===year:new Date(Number(key)*1000).getFullYear()===year);return pair?Number(pair[1])||0:null}
function renderCoverFan(covers,status){if(status==='loading')return '<span class="cover-placeholder cover-loading">正在整理<br>代表读物</span>';if(!covers.length)return `<span class="cover-placeholder">${status==='failed'?'年度数据<br>暂未取到':'暂无<br>代表读物'}</span>`;return covers.map((book,index)=>book.cover?`<img src="${esc(book.cover)}" alt="《${esc(book.title)}》" width="86" height="122" loading="lazy" decoding="async" style="--cover:${index}">`:`<span class="cover-sheet" role="img" aria-label="《${esc(book.title)}》无封面占位" style="--cover:${index};--cover-tone:${categoryTone(book.category)}"><small>${esc(book.author||'年度代表读物')}</small><b>${esc(book.title)}</b></span>`).join('')}
function renderYearTimeline(){const target=$('#yearTimeline');if(!target)return;const years=Array.from({length:nowYear-Math.max(archiveStartYear(),2000)+1},(_,i)=>nowYear-i);target.innerHTML=years.map(year=>{const stats=state.yearSummaries.get(year),status=state.demo?'ready':state.yearTimelineStatus.get(year)||(stats?'ready':'loading'),seconds=stats?.totalReadTime??yearBucketSeconds(year),count=stats?yearReadCount(stats):null,covers=stats?yearCovers(stats):[],countLabel=count==null?(status==='failed'?'本数暂缺':'正在读取…'):`${count.toLocaleString()} 本`,timeLabel=seconds==null?'时长暂缺':duration(seconds);return `<button class="year-card ${year===state.year?'active':''} ${status}" data-year="${year}" ${status==='loading'?'aria-busy="true"':''}><div><div class="year-card-title"><strong>${year}</strong>${year===nowYear?'<span>阅读中</span>':''}</div><p><span>${countLabel}</span><i></i><em>${timeLabel}</em></p>${year===nowYear?'<small class="year-scope">截至今天</small>':'<small class="year-scope">完整自然年</small>'}</div><div class="cover-fan">${renderCoverFan(covers,status)}</div></button>`}).join('');$$('.year-card').forEach(card=>card.onclick=async()=>{const year=Number(card.dataset.year);state.year=year;$('#yearSelect').value=String(year);document.querySelector('#annual').scrollIntoView({block:'start'});await loadPeriod('annually',year)})}
async function loadYearTimeline(epoch=state.timelineEpoch){const years=Array.from({length:nowYear-Math.max(archiveStartYear(),2000)+1},(_,i)=>nowYear-i).filter(year=>!state.yearSummaries.has(year));let failures=0;years.forEach(year=>state.yearTimelineStatus.set(year,'loading'));renderYearTimeline();for(let i=0;i<years.length;i+=3){const batch=years.slice(i,i+3),results=await Promise.allSettled(batch.map(year=>api('/readdata/detail',{mode:'annually',baseTime:yearTimestamp(year)})));if(epoch!==state.timelineEpoch)return;results.forEach((result,index)=>{const year=batch[index];if(result.status==='fulfilled'){state.yearSummaries.set(year,result.value);state.yearTimelineStatus.set(year,'ready')}else{state.yearTimelineStatus.set(year,'failed');failures+=1}});renderYearTimeline()}toast(failures?`阅读生涯已整理，${failures} 个年度暂未取到`:'阅读生涯已整理完成')}
function renderLifetimeInsights(){const stats=state.overall||{},longest=stats.readLongest||[],categories=(stats.preferCategory||[]).filter(item=>item.readingTime||item.readingCount).slice(0,7),authors=(stats.preferAuthor||[]).slice(0,6),max=Math.max(...categories.map(item=>Number(item.readingTime)||0),1);$('#lifetimeLongest').innerHTML=longest.length?longest.slice(0,6).map((entry,index)=>{const book=normalizeReadingItem(entry);return `<li ${book.bookId?`role="button" tabindex="0" data-book="${esc(book.bookId)}" aria-label="查看《${esc(book.title)}》详情"`:''}><b>${String(index+1).padStart(2,'0')}</b><div><strong>${esc(book.title)}</strong><small>${esc(book.author||book.category)}</small><i><span style="--read-share:${Math.max(.06,(Number(entry.readTime)||0)/Math.max(Number(longest[0]?.readTime)||1,1))}"></span></i></div><em>${duration(entry.readTime)}</em></li>`}).join(''):'<li class="archive-empty"><strong>还没有累计阅读排行</strong><small>微信读书累计统计中暂时没有达到展示条件的读物。</small></li>';$('#lifetimeLongest').querySelectorAll('[data-book]').forEach(item=>item.onclick=()=>openBook(item.dataset.book));$('#lifetimePreferences').innerHTML=categories.length?`<div class="archive-preference-list">${categories.map(item=>`<div><header><span><i style="--tone:${categoryTone(item.categoryTitle)}"></i>${esc(item.categoryTitle||'其他')}</span><em>${duration(item.readingTime)}</em></header><b><span style="--share:${Math.max(.04,(Number(item.readingTime)||0)/max)};--tone:${categoryTone(item.categoryTitle)}"></span></b></div>`).join('')}</div>${authors.length?`<div class="archive-authors"><small>偏好作者</small><p>${authors.map(author=>`<span>${esc(author.name)} <b>${author.count||0}本</b></span>`).join('')}</p></div>`:''}`:emptyState('偏好仍在形成','有足够阅读时长后，这里会出现分类和作者偏好。');renderLifetimePortrait(stats)}
