function portraitDimensions(s,{lifetime=false}={}){const readDays=Number(s.readDays)||0,totalReadTime=Number(s.totalReadTime)||0,readCount=statNumber(s,'读过'),finished=statNumber(s,'读完'),statNotes=statNumber(s,'笔记'),notes=statNotes??(lifetime?(state.notebooks?.totalNoteCount??null):null),categories=(s.preferCategory||[]).filter(item=>item.readingTime||item.readingCount),categoryTime=categories.reduce((sum,item)=>sum+(Number(item.readingTime)||0),0),topCategory=categories[0],topShare=categoryTime?Math.round((Number(topCategory?.readingTime)||0)/categoryTime*100):null,readDayAvg=readDays?Math.round(totalReadTime/readDays/60):null,finishRate=readCount&&finished!=null?Math.round(finished/readCount*100):null,avgNotes=readCount&&notes!=null?Math.round(notes/readCount):null,persistence=lifetime?Math.round(readDays/readingYears()):readDays;return[{name:'专注',score:scoreClamp((readDayAvg||0)/60*100),raw:readDayAvg==null?'阅读日均暂无':`阅读日均 ${readDayAvg} 分钟`,rule:'60 分钟达到满刻度'},{name:'广度',score:scoreClamp(categories.length/8*100),raw:`${categories.length} 个有效分类`,rule:'8 个分类达到满刻度'},{name:'深度',score:scoreClamp(finishRate),raw:finishRate==null?'完读率暂无':`完读率 ${finishRate}%`,rule:'按同周期读完 / 读过'},{name:'坚持',score:scoreClamp(persistence/100*100),raw:lifetime?`年均 ${persistence} 个阅读日`:`${readDays} 个阅读日`,rule:'年均 100 个阅读日满刻度'},{name:'笔记',score:scoreClamp((avgNotes||0)/16*100),raw:avgNotes==null?'笔记均值暂无':`均 ${avgNotes} 条/本`,rule:'每本 16 条达到满刻度'},{name:'专精',score:scoreClamp((topShare||0)/50*100),raw:topShare==null?'分类集中度暂无':`${topCategory?.categoryTitle||'首类'}占 ${topShare}%`,rule:'首类占 50% 达到满刻度'}]}
function portraitMarkup(dims,{compact=false,lifetime=false}={}){const points=dims.map((dimension,index)=>radarPoint(index,dimension.score)),labelPoints=Array.from({length:6},(_,index)=>radarPoint(index,100,198)),svg=`<div class="radar-wrap"><svg class="radar-svg" viewBox="0 0 600 500" role="img" aria-label="六维阅读画像：${dims.map(dimension=>`${dimension.name}${dimension.score}分`).join('，')}">${[25,50,75,100].map(value=>`<polygon class="radar-grid" points="${radarPolygon(value)}"/>`).join('')}${Array.from({length:6},(_,index)=>{const point=radarPoint(index,100);return`<line class="radar-axis" x1="300" y1="240" x2="${point[0]}" y2="${point[1]}"/>`}).join('')}<polygon class="radar-area radar-animate" points="${points.map(point=>point.join(',')).join(' ')}"/>${points.map((point,index)=>`<circle class="radar-point radar-animate" style="--delay:${420+index*70}ms" cx="${point[0]}" cy="${point[1]}" r="6"><title>${dims[index].name} ${dims[index].score}分 · ${dims[index].raw}</title></circle>`).join('')}${labelPoints.map((point,index)=>`<text class="radar-label" x="${point[0]}" y="${point[1]-4}" text-anchor="${point[0]<280?'end':point[0]>320?'start':'middle'}">${dims[index].name}</text><text class="radar-score" x="${point[0]}" y="${point[1]+15}" text-anchor="${point[0]<280?'end':point[0]>320?'start':'middle'}">${dims[index].score}</text>`).join('')}</svg></div>`;if(compact)return`<div class="compact-portrait-layout">${svg}<div class="compact-dimensions">${dims.map((dimension,index)=>`<div style="--tone:${index%2?'#2c5234':'#819985'}"><i></i><span>${dimension.name}</span><strong>${dimension.score}</strong><small>${dimension.raw}</small></div>`).join('')}</div><p class="compact-method">透明阈值归一化至 0–100；累计画像按注册至今的年均阅读日计算。</p></div>`;return`<div class="portrait-layout">${svg}<div class="portrait-legend">${dims.map((dimension,index)=>`<section class="portrait-dimension" style="--tone:${index%2?'#2c5234':'#819985'}"><i></i><header><h4>${dimension.name}</h4><strong>${dimension.score}</strong></header><p>${dimension.raw} · ${dimension.rule}</p></section>`).join('')}<p class="portrait-method">画像分数是个人趋势刻度：采用透明阈值归一化到 0–100，仅用于比较你自己的不同年份。原始数据来自微信读书${lifetime?'累计':'年度'}统计、书架与笔记本。</p></div></div>`}
