async function openBook(bookId){if(!bookId)return;const request=++state.drawerRequest,drawer=$('#bookDrawer');state.selected=bookId;drawer.dataset.bookId=bookId;drawer.removeAttribute('aria-labelledby');drawer.setAttribute('aria-label','正在载入书籍详情');drawer.scrollTop=0;drawer.classList.add('open');$('#drawerBackdrop').classList.add('open');drawer.setAttribute('aria-hidden','false');$('#drawerContent').innerHTML='<p class="empty">正在读取详情、进度、划线、想法和点评…</p>';if(state.demo){if(request===state.drawerRequest)renderDemoDrawer(bookId);return}try{const [info,progress,bookmarks,mine,popular,publicReviews]=await Promise.all([api('/book/info',{bookId}),api('/book/getprogress',{bookId}),api('/book/bookmarklist',{bookId}),loadMine(bookId),api('/book/bestbookmarks',{bookId,chapterUid:0,synckey:0}),api('/review/list',{bookId,reviewListType:0,count:20,maxIdx:0,synckey:0})]);if(request!==state.drawerRequest)return;renderDrawer({info,progress,bookmarks,mine,popular,publicReviews})}catch(e){if(request===state.drawerRequest)$('#drawerContent').innerHTML=`<p class="empty">${esc(e.message)}</p>`}}
