function renderHighlightItems(highlights,chapters,q=''){const query=String(q).toLowerCase(),items=highlights.filter(item=>`${item.markText}${chapters.get(String(item.chapterUid))||''}`.toLowerCase().includes(query));return items.map(item=>`<article class="highlight"><small>${esc(chapters.get(String(item.chapterUid))||'未归类章节')} · ${date(item.createTime)}</small><blockquote>“${esc(item.markText)}”</blockquote></article>`).join('')||emptyState(query?'没有匹配的划线':'还没有划线',query?'换一个关键词，或清空搜索框查看全部划线。':'这本书暂时没有可展示的个人划线。')}
function renderThoughtItems(thoughts,q=''){const query=String(q).toLowerCase(),items=thoughts.filter(item=>`${item.abstract||''}${item.content||''}${item.chapterName||''}`.toLowerCase().includes(query));return items.map(item=>`<article class="highlight thought-card"><small>${esc(item.chapterName||'个人想法')} · ${date(item.createTime)}</small>${item.abstract?`<blockquote>“${esc(item.abstract)}”</blockquote>`:''}<p>${esc(item.content||'')}</p></article>`).join('')||emptyState(query?'没有匹配的想法':'还没有想法',query?'换一个关键词，或清空搜索框查看全部想法。':'这本书暂时没有可展示的个人想法。')}

function download(name,type,content){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
