function exportNotes(){const rows=(state.notebooks?.books||[]).map(x=>({bookId:x.bookId,title:x.book?.title,author:x.book?.author,highlights:x.noteCount||0,thoughts:x.reviewCount||0,bookmarks:x.bookmarkCount||0,total:noteCount(x),progress:x.readingProgress}));download('读迹-笔记索引.json','application/json',JSON.stringify(rows,null,2));toast('笔记索引已导出')}
function exportBook(type){const d=state.drawerData;if(!d)return;if(type==='json')return download(`${d.info.title}-笔记.json`,'application/json',JSON.stringify({book:d.info,progress:d.progress,highlights:d.highlights,thoughts:d.thoughts},null,2));const lines=[`# ${d.info.title}`,``, `作者：${d.info.author||'未知'}`,`阅读进度：${d.progress.book?.progress??0}%`,``,`## 划线`,...d.highlights.flatMap(x=>[``, `> ${x.markText}`,``, `${date(x.createTime)}`]),``,`## 想法`,...d.thoughts.flatMap(x=>[``,x.abstract?`> ${x.abstract}`:'',``,x.content||'',date(x.createTime)])];download(`${d.info.title}-笔记.md`,'text/markdown;charset=utf-8',lines.join('\n'))}

function configureConnectionCopy(){
  if(!apiBase)return;
  $('#keyDialogDescription').textContent='在线页面会把 API Key 直接交给你电脑上的读迹连接器，再由连接器读取微信读书数据。请先在本机运行连接器。';
  $('#keyDialogPrivacy').querySelector('p').innerHTML='<strong>Key 不会发送到 GitHub。</strong>它只在输入时短暂停留于当前页面，并通过回环地址交给本机 Node 进程；不写入 localStorage、sessionStorage、页面源码或日志，点击清除连接或停止连接器即可清除。';
  $('.key-memory-badge').lastChild.textContent='本机连接器';
  $('.privacy').textContent='◉ API Key 不会发送到 GitHub，仅交给 127.0.0.1 本机连接器并保留在进程内存';
  $('.lede').textContent='从你的微信读书数据中，看见时间、偏好与积累。在线版使用真实数据前，需要先启动本机连接器。';
  if($('#connectorHelp'))$('#connectorHelp').hidden=false;
  $('footer span').textContent='读迹 · Tools 在线版';
}

function setKeyError(message=''){
  const error=$('#keyDialogError');
  error.textContent=message;
  error.hidden=!message;
  $('#apiKeyInput').setAttribute('aria-invalid',message?'true':'false');
}

function setKeyBusy(busy){
  $('#keySave').disabled=busy;
  $('#keyClear').disabled=busy;
  $('#keyCancel').disabled=busy;
  $('#apiKeyInput').disabled=busy;
  $('#keyVisibility').disabled=busy;
  $('#keyForm').classList.toggle('is-busy',busy);
  $('.key-save-label').textContent=busy?'正在连接…':state.connectionConfigured?'更新并连接':'保存并连接';
}

function updateConnection(configured,{offline=false}={}){
  state.connectionConfigured=Boolean(configured);
  const connection=$('#connection'),label=connection.querySelector('span');
  connection.classList.toggle('ok',state.connectionConfigured);
  label.textContent=state.connectionConfigured?'微信读书已连接':offline?(apiBase?'启动本地连接器':'本地服务不可用'):apiBase?'连接本机数据':'配置 API Key';
  connection.setAttribute('aria-label',state.connectionConfigured?'微信读书已连接，管理 API Key':label.textContent);
  $('#keyClear').hidden=!state.connectionConfigured;
  $('.key-save-label').textContent=state.connectionConfigured?'更新并连接':'保存并连接';
}

function resetKeyField(){
  const input=$('#apiKeyInput');
  input.value='';
  input.type='password';
  input.disabled=false;
  $('#keyVisibility').disabled=false;
  $('#keyVisibility').setAttribute('aria-pressed','false');
  $('#keyVisibility').setAttribute('aria-label','显示 API Key');
  $('.key-visibility-label').textContent='显示';
  setKeyError();
}

function openKeyDialog(){
  const dialog=$('#keyDialog');
  resetKeyField();
  $('#keyClear').hidden=!state.connectionConfigured;
  if(!dialog.open)dialog.showModal();
  requestAnimationFrame(()=>$('#apiKeyInput').focus());
}

function closeKeyDialog(){
  const dialog=$('#keyDialog');
  if(dialog.open)dialog.close();
  resetKeyField();
  $('#connection').focus({preventScroll:true});
}

async function checkConnectionStatus(){
  try{
    const response=await connectorFetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(4000)});
    const result=await readResponseJson(response);
    if(!response.ok)throw new Error(result.message||'连接器状态读取失败');
    updateConnection(result.configured);
    return Boolean(result.configured);
  }catch{
    updateConnection(false,{offline:true});
    return false;
  }
}

async function initializeConnection(){
  configureConnectionCopy();
  if(apiBase){updateConnection(false);return false}
  return checkConnectionStatus();
}

async function openConnectionManager(){
  openKeyDialog();
  if(apiBase)await checkConnectionStatus();
}

async function saveApiKey(event){
  event.preventDefault();
  const input=$('#apiKeyInput');
  let apiKey=input.value.trim();
  if(!/^wrk-[A-Za-z0-9_-]{20,}$/.test(apiKey)){
    setKeyError('请输入完整的 wrk- 开头 API Key。');
    input.focus();
    return;
  }
  setKeyError();
  setKeyBusy(true);
  try{
    const requestBody=JSON.stringify({apiKey});
    apiKey='';
    input.value='';
    const response=await connectorFetch('/api/config',{method:'POST',headers:{'content-type':'application/json'},body:requestBody,signal:AbortSignal.timeout(8000)});
    const result=await readResponseJson(response);
    if(!response.ok)throw new Error(result.message||'API Key 保存失败');
    updateConnection(true);
    closeKeyDialog();
    toast('连接已建立，正在载入你的阅读数据');
    await loadInitial();
  }catch(error){
    input.value='';
    setKeyError(error.name==='TimeoutError'?'连接超时，请确认本机连接器已经启动。':error.message||'连接失败，请稍后重试。');
  }finally{
    setKeyBusy(false);
  }
}

async function clearApiKey(){
  setKeyBusy(true);
  try{
    const response=await connectorFetch('/api/config',{method:'DELETE',signal:AbortSignal.timeout(5000)});
    const result=await readResponseJson(response);
    if(!response.ok)throw new Error(result.message||'清除连接失败');
    updateConnection(false);
    closeKeyDialog();
    activateDemo();
    toast('API Key 已从本机进程清除');
  }catch(error){
    setKeyError(error.name==='TimeoutError'?'连接器没有响应，请稍后重试。':error.message||'清除连接失败');
  }finally{
    setKeyBusy(false);
  }
}

async function loadOrConfigure(){
  if(!state.connectionConfigured&&apiBase&&await checkConnectionStatus())return loadInitial();
  if(!state.connectionConfigured){openKeyDialog();return false}
  return loadInitial();
}

