function activateDemo(){state.timelineEpoch+=1;Object.assign(state,demo,{demo:true,year:state.year,mode:state.mode,visibleBooks:30});state.annualStats=demo.stats;state.yearSummaries=new Map(Array.from({length:Math.min(8,readingYears())},(_,index)=>{const year=nowYear-index,factor=Math.max(.35,1-index*.07),read=Math.max(8,38-index*3),finished=Math.max(4,Math.round(read*.55)),representatives=Array.from({length:Math.min(5,demo.shelf.books.length)},(_,offset)=>{const book=demo.shelf.books[(index+offset)%demo.shelf.books.length];return{book:{...book},readTime:Math.round((5-offset)*7600*factor)}}),stats={...demo.stats,totalReadTime:Math.round(demo.stats.totalReadTime*factor),readLongest:representatives,readStat:demo.stats.readStat.map(item=>item.stat==='读过'?{...item,counts:`${read}本`}:item.stat==='读完'?{...item,counts:`${finished}本`}:item.stat==='笔记'?{...item,counts:`${Math.round(read*5.7)}条`}:item)};return[year,stats]}));state.yearTimelineStatus=new Map([...state.yearSummaries.keys()].map(year=>[year,'ready']));setupYears();render();toast('正在预览演示数据')}

